mapper.select:
select 

from S02V001T
where APKIHONCD = #{apkihoncd,jdbcType=VARCHAR}
  and SHOPCD = #{shopcd,jdbcType=VARCHAR}
  and SHNCD = #{shncd,jdbcType=VARCHAR}

SELECT * FROM ( SELECT SHOHIN_MST_VIEW.APKIHONCD ,SHOHIN_MST_VIEW.SHOPCD ,SHOHIN_MST_VIEW.SHNCD ,SHOHIN_MST_VIEW.SHNNMKIRIKAEDD ,SHOHIN_MST_VIEW.GENZSHNNM ,SHOHIN_MST_VIEW.SHINSHNNM ,SHOHIN_MST_VIEW.STKBN ,SHOHIN_MST_VIEW.HYOJUNPRICEKIRIKAEDD ,SHOHIN_MST_VIEW.GENZPRICEKBN ,SHOHIN_MST_VIEW.SHINPRICEKBN ,SHOHIN_MST_VIEW.LCTGRYCD ,SHOHIN_MST_VIEW.MCTGRYCD ,SHOHIN_MST_VIEW.SCTGRYCD ,SHOHIN_MST_VIEW.HANBAISTRTDD ,SHOHIN_MST_VIEW.HANBAISHRYDD ,SHOHIN_MST_VIEW.SHOPYUKOKBN ,YUKOKBNNM.ITEMNM AS YUKOKBNNM ,STKBNMEI.ITEMNM AS STKBNMEI ,GENZPRICEKBNMEI.ITEMNM AS GENZPRICEKBNMEI ,SHINPRICEKBNMEI.ITEMNM AS SHINPRICEKBNMEI FROM S02V001T SHOHIN_MST_VIEW LEFT OUTER JOIN S01M004T YUKOKBNNM ON YUKOKBNNM.CONDITIONID = 'CN001' AND YUKOKBNNM.SETTEIATAI = SHOHIN_MST_VIEW.SHOPYUKOKBN LEFT OUTER JOIN S01M004T STKBNMEI ON STKBNMEI.CONDITIONID = 'CN025' AND STKBNMEI.SETTEIATAI = SHOHIN_MST_VIEW.STKBN LEFT OUTER JOIN S01M004T GENZPRICEKBNMEI ON GENZPRICEKBNMEI.CONDITIONID = 'CN028' AND GENZPRICEKBNMEI.SETTEIATAI = SHOHIN_MST_VIEW.GENZPRICEKBN LEFT OUTER JOIN S01M004T SHINPRICEKBNMEI ON SHINPRICEKBNMEI.CONDITIONID = 'CN028' AND SHINPRICEKBNMEI.SETTEIATAI = SHOHIN_MST_VIEW.SHINPRICEKBN WHERE SHOHIN_MST_VIEW.APKIHONCD = #{apkihoncd,jdbcType=VARCHAR} AND SHOHIN_MST_VIEW.SHOPCD = #{shopcd,jdbcType=VARCHAR}
AND SHOHIN_MST_VIEW.STKBN IN
#{item}
AND SHOHIN_MST_VIEW.SHNCD LIKE #{shncd,jdbcType=VARCHAR} ||'%'
AND (CASE WHEN #{unyoYmd,jdbcType=VARCHAR} < SHOHIN_MST_VIEW.SHNNMKIRIKAEDD THEN SHOHIN_MST_VIEW.GENZSHNNM ELSE SHINSHNNM END) LIKE '%'|| #{shnnm,jdbcType=VARCHAR} ||'%'
AND SHOHIN_MST_VIEW.LCTGRYCD = #{lctgrycd,jdbcType=VARCHAR}
AND SHOHIN_MST_VIEW.MCTGRYCD = #{mctgrycd,jdbcType=VARCHAR}
AND SHOHIN_MST_VIEW.SCTGRYCD = #{sctgrycd,jdbcType=VARCHAR}
AND (CASE WHEN #{unyoYmd,jdbcType=VARCHAR} < SHOHIN_MST_VIEW.HYOJUNPRICEKIRIKAEDD THEN SHOHIN_MST_VIEW.GENZPRICEKBN ELSE SHINPRICEKBN END) IN
#{item}
AND SHOHIN_MST_VIEW.HANBAISTRTDD BETWEEN #{hanbaistrtddstr,jdbcType=VARCHAR} AND #{hanbaistrtddend,jdbcType=VARCHAR}
AND SHOHIN_MST_VIEW.HANBAISHRYDD BETWEEN #{hanbaishryddstr,jdbcType=VARCHAR} AND #{hanbaishryddend,jdbcType=VARCHAR}
AND SHOHIN_MST_VIEW.SHOPYUKOKBN = #{yukokbn1,jdbcType=VARCHAR}
AND SHOHIN_MST_VIEW.SHOPYUKOKBN = #{yukokbn2,jdbcType=VARCHAR}
ORDER BY SHOHIN_MST_VIEW.APKIHONCD ,SHOHIN_MST_VIEW.SHOPCD ,SHOHIN_MST_VIEW.SHNCD ) WHERE ROWNUM <= #{rownum} + 1

SELECT TST.STSHNCD ,TST.TOKUISAKICD ,TST.TEKIYOSTRTDD ,TST.TEKIYOSHRYDD ,TST.DLVRYPRICE ,TST.MOCHIKAERIPRICE ,TST.YUKOKBN ,TSM.TOKUISAKINMN1 ,TSM.TOKUISAKIKBN ,TSM.JIGYOSHOCD ,TOKUISAKIKBNMEI.ITEMNM AS TOKUISAKIKBNMEI ,YUKOKBNNM.ITEMNM AS YUKOKBNNM FROM S02M066T TST INNER JOIN S02M013T TSM ON TSM.APKIHONCD = TST.APKIHONCD AND TSM.SHOPCD = TST.SHOPCD AND TSM.TOKUISAKICD = TST.TOKUISAKICD LEFT OUTER JOIN S01M004T TOKUISAKIKBNMEI ON TOKUISAKIKBNMEI.CONDITIONID = 'CN100' AND TOKUISAKIKBNMEI.SETTEIATAI = TSM.TOKUISAKIKBN LEFT OUTER JOIN S01M004T YUKOKBNNM ON YUKOKBNNM.CONDITIONID = 'CN001' AND YUKOKBNNM.SETTEIATAI = TST.YUKOKBN WHERE TST.APKIHONCD = #{apkihoncd,jdbcType=VARCHAR} AND TST.SHOPCD = #{shopcd,jdbcType=VARCHAR} AND TST.STSHNCD = #{shncd,jdbcType=VARCHAR}
AND TSM.JIGYOSHOCD = #{jigyoshocd,jdbcType=VARCHAR}
ORDER BY TST.TOKUISAKICD, TST.TEKIYOSTRTDD

SELECT SHMV.APKIHONCD APKIHONCD, SHMV.SHOPCD SHOPCD, ZYKT.APKIHONCD ZAIKOAPKIHONCD, ZYKT.SHIMEDYDM SHIMEDYDM, SHMV.SHNCD SHNCD, SHMV.GENZSHNNM GENZSHNNM, SHMV.SHINSHNNM SHINSHNNM, SHMV.SHNNMKIRIKAEDD SHNNMKIRIKAEDD, SHMV.IRO IRO, SYKM1.MOJISETTEIATAI SZNM, SHMV.URIIRISU URIIRISU, SYKM2.MOJISETTEIATAI IRISUTANI, SHMV.GENKAKEISANKBN GENKAKEISANKBN, SHMV.HYOJUNGENKA HYOJUNGENKA, SHMV.ZAIKOUNT ZAIKOUNTMST, ZYKT.ZAIKOUNT ZAIKOUNTTBL, NVL(ZYKT.TOTSUKIMATSUZAIKOKAZU,0) TOTSUKIMATSUZAIKOKAZU, ZYKT.TOTSUKITNORSSURYO TOTSUKITNORSSURYO, ZYKT.KSHNSYSTMYMD KSHNSYSTMYMD, ZYKT.KSHNSYSTMJIKAN KSHNSYSTMJIKAN, ZYKT.KOSHACD KOSHACD, ZYKT.TOTSUKIKFSKSURYO TOTSUKIKFSKSURYO, ZYKT.SOKOCD SOKOCD, ZYKT.MAEDMMATSUZAIKOKAZU MAEDMMATSUZAIKOKAZU, ZYKT.TOTSUKISIIREKAZU TOTSUKISIIREKAZU, ZYKT.TOTSUKISIIREKIN TOTSUKISIIREKIN, ZYKT.TOTSUKISEIZOKAZU TOTSUKISEIZOKAZU, ZYKT.TOTSUKICHOSEINYUKOKAZU TOTSUKICHOSEINYUKOKAZU, ZYKT.TOTSUKISONOTANYUKOKAZU TOTSUKISONOTANYUKOKAZU, ZYKT.TOTSUKIURIKAZU TOTSUKIURIKAZU, ZYKT.TOTSUKICHOSEISHUKKOKAZU TOTSUKICHOSEISHUKKOKAZU, ZYKT.TOTSUKIKEIHISHUKKOKAZU TOTSUKIKEIHISHUKKOKAZU, ZYKT.TOTSUKISONOTASHUKKOKAZU TOTSUKISONOTASHUKKOKAZU, ZYKT.SHIMEFLG SHIMEFLG, ZYKT.YUKOKBN YUKOKBN, ZYKT.TOSHAAPKIHONCD TOSHAAPKIHONCD, ZYKT.TOSHASHOPCD TOSHASHOPCD, ZYKT.TOSHACD TOSHACD, ZYKT.INPTSYSTMYMD INPTSYSTMYMD, ZYKT.INPTSYSTMJIKAN INPTSYSTMJIKAN, ZYKT.INPTUNYOYMD INPTUNYOYMD, ZYKT.INPTIPADRSE INPTIPADRSE, ZYKT.INPTPGMID INPTPGMID, ZYKT.KOSHAAPKIHONCD KOSHAAPKIHONCD, ZYKT.KOSHASHOPCD KOSHASHOPCD, ZYKT.KSHNUNYOYMD KSHNUNYOYMD, ZYKT.KSHNIPADRSE KSHNIPADRSE, ZYKT.KSHNPGMID KSHNPGMID FROM S02V001T SHMV LEFT OUTER JOIN S13T002T ZYKT ON( ZYKT.APKIHONCD = SHMV.APKIHONCD AND ZYKT.SHOPCD = SHMV.SHOPCD AND ZYKT.SOKOCD = #{sokocd,jdbcType=VARCHAR} AND ZYKT.SHNCD = SHMV.SHNCD AND ZYKT.SHIMEDYDM = #{getsujishimedydm,jdbcType=VARCHAR} ) LEFT OUTER JOIN S02M006T SYKM1 ON( SYKM1.APKIHONCD = '000' AND SYKM1.SHOPCD = '000' AND SYKM1.RCRDKBN = 'M' AND SYKM1.SETTEINO = '037' AND SYKM1.SETTEICD = SHMV.SZ ) LEFT OUTER JOIN S02M006T SYKM2 ON( SYKM2.APKIHONCD = '000' AND SYKM2.SHOPCD = '000' AND SYKM2.RCRDKBN = 'M' AND SYKM2.SETTEINO = '013' AND SYKM2.SETTEICD = SHMV.URITANI ) WHERE SHMV.ZAIKOKANRITRGTFLG = '1' AND SHMV.SHOPYUKOKBN = '1' AND SHMV.APKIHONCD = #{apkihoncd,jdbcType=VARCHAR} AND SHMV.SHOPCD = #{shopcd,jdbcType=VARCHAR}
AND SHMV.LCTGRYCD = #{lctgrycd,jdbcType=VARCHAR}
ORDER BY SHMV.LCTGRYCD, SHMV.SHNCD

SELECT * FROM ( SELECT SHMV.APKIHONCD ,SHMV.SHOPCD ,SHMV.SHNCD ,SHMV.SHNNMKIRIKAEDD ,SHMV.GENZSHNNM ,SHMV.SHINSHNNM ,SHMV.STKBN ,STKBNNM.ITEMNM AS STKBNNM ,SHMV.HYOJUNPRICEKIRIKAEDD ,SHMV.GENZPRICEKBN ,GENZPRICEKBNNM.ITEMNM AS GENZPRICEKBNNM ,SHMV.SHINPRICEKBN ,SHINPRICEKBNNM.ITEMNM AS SHINPRICEKBNNM ,SHMV.LCTGRYCD ,SHMV.MCTGRYCD ,SHMV.SCTGRYCD ,SHMV.HANBAISTRTDD ,SHMV.HANBAISHRYDD ,SHMV.SHOPYUKOKBN ,YUKOKBNNM.ITEMNM AS YUKOKBNNM FROM S02V001T SHMV LEFT OUTER JOIN S01M004T YUKOKBNNM ON YUKOKBNNM.CONDITIONID = 'CN001' AND YUKOKBNNM.SETTEIATAI = SHMV.SHOPYUKOKBN LEFT OUTER JOIN S01M004T STKBNNM ON STKBNNM.CONDITIONID = 'CN025' AND STKBNNM.SETTEIATAI = SHMV.STKBN LEFT OUTER JOIN S01M004T GENZPRICEKBNNM ON GENZPRICEKBNNM.CONDITIONID = 'CN028' AND GENZPRICEKBNNM.SETTEIATAI = SHMV.GENZPRICEKBN LEFT OUTER JOIN S01M004T SHINPRICEKBNNM ON SHINPRICEKBNNM.CONDITIONID = 'CN028' AND SHINPRICEKBNNM.SETTEIATAI = SHMV.SHINPRICEKBN WHERE SHMV.APKIHONCD = #{apkihoncd,jdbcType=VARCHAR} AND SHMV.SHOPCD = #{shopcd,jdbcType=VARCHAR}
AND SHMV.STKBN IN
#{item}
AND SHMV.SHNCD LIKE #{shncd,jdbcType=VARCHAR} ||'%'
AND (CASE WHEN #{unyoymd,jdbcType=VARCHAR} < SHMV.SHNNMKIRIKAEDD THEN SHMV.GENZSHNNM ELSE SHINSHNNM END) LIKE '%'|| #{shnnm,jdbcType=VARCHAR} ||'%'
AND SHMV.LCTGRYCD = #{lctgrycd,jdbcType=VARCHAR}
AND SHMV.MCTGRYCD = #{mctgrycd,jdbcType=VARCHAR}
AND SHMV.SCTGRYCD = #{sctgrycd,jdbcType=VARCHAR}
AND (CASE WHEN #{unyoymd,jdbcType=VARCHAR} < SHMV.HYOJUNPRICEKIRIKAEDD THEN SHMV.GENZPRICEKBN ELSE SHINPRICEKBN END) IN
#{item}
AND SHMV.HANBAISTRTDD BETWEEN #{hanbaistrtddstr,jdbcType=VARCHAR} AND #{hanbaistrtddend,jdbcType=VARCHAR}
AND SHMV.HANBAISHRYDD BETWEEN #{hanbaishryddstr,jdbcType=VARCHAR} AND #{hanbaishryddend,jdbcType=VARCHAR}
AND SHMV.SHOPYUKOKBN = #{yukokbn1,jdbcType=VARCHAR}
AND SHMV.SHOPYUKOKBN = #{yukokbn2,jdbcType=VARCHAR}
ORDER BY SHMV.APKIHONCD ,SHMV.SHOPCD ,SHMV.SHNCD ) WHERE ROWNUM <= #{rownum} + 1

SELECT
    SHMV.SHNCD
   ,CASE
        WHEN #{unyodd,jdbcType=VARCHAR}  >=  SHMV.SHNNMKIRIKAEDD THEN
            SHMV.SHINSHNNMRYAKUSHO
        ELSE SHMV.GENZSHNNMRYAKUSHO
    END AS SHNNMRYAKUSHO
   ,CASE
        WHEN #{unyodd,jdbcType=VARCHAR}  >=  SHMV.HYOJUNPRICEKIRIKAEDD THEN
            SHMV.SHINHYOJUNPRICE
        ELSE SHMV.GENZHYOJUNPRICE
    END AS HYOJUNPRICE
   ,SHMV.TAXSETTEIKBN
   ,SHMV.TAXKBN
FROM
    S02V001T SHMV
INNER JOIN S02M006T SKM
    ON  SKM.APKIHONCD = #{constapkihoncd000,jdbcType=VARCHAR}
    AND SKM.SHOPCD = #{constshopcd000,jdbcType=VARCHAR}
    AND SKM.SETTEINO = #{constsetteino096,jdbcType=VARCHAR}
    AND SKM.RCRDKBN = #{constrecordkbnm,jdbcType=VARCHAR}
    AND SKM.SETTEICD = #{constsetteicd096_3,jdbcType=VARCHAR}
    AND SKM.MOJISETTEIATAI = SHMV.LCTGRYCD
WHERE
    SHMV.APKIHONCD = #{apkihoncd,jdbcType=VARCHAR}
AND SHMV.SHOPCD = #{shopcd,jdbcType=VARCHAR}
AND SHMV.KIHONSHNYUKOKBN = #{constyukokbn1,jdbcType=VARCHAR}
AND SHMV.SHOPYUKOKBN = #{constyukokbn1,jdbcType=VARCHAR}
ORDER BY
    SHMV.SHNCD ASC

SELECT SHMV.APKIHONCD APKIHONCD, SHMV.SHOPCD SHOPCD, SHPM.SHOPNM SHOPNM, TTSM1.TNSHAMEI TNSHAMEI, SKOM.DLVRYKYOTENCD DLVRYKYOTENCD, HKNM.DLVRYKYOTENNM DLVRYKYOTENNM, SHMV.LCTGRYCD LCTGRYCD, SCGM.LCTGRYNM LCTGRYNM, SHMV.SHNCD SHNCD, SHMV.GENZSHNNM GENZSHNNM, SHMV.SHINSHNNM SHINSHNNM, SHMV.SHNNMKIRIKAEDD SHNNMKIRIKAEDD, SHMV.IRO IRO, SYKM1.MOJISETTEIATAI SZNM, SHMV.URIIRISU URIIRISU, SYKM2.MOJISETTEIATAI IRISUTANI, SHMV.GENKAKEISANKBN GENKAKEISANKBN, NVL(SHMV.HYOJUNGENKA,0) HYOJUNGENKA, NVL(SHMV.ZAIKOUNT,0) ZAIKOUNTMST, NVL(ZYKT.ZAIKOUNT,0) ZAIKOUNTTBL, NVL(ZYKT.TOTSUKIMATSUZAIKOKAZU, 0) TOTSUKIMATSUZAIKOKAZU, ZYKT.TOTSUKITNORSSURYO TOTSUKITNORSSURYO, ZYKT.TOTSUKIKFSKSURYO TOTSUKIKFSKSURYO, ZYKT.SHIMEDYDM SHIMEDYDM, ZYKT.SHIMEFLG SHIMEFLG FROM S02V001T SHMV LEFT OUTER JOIN S13T002T ZYKT ON ( SHMV.APKIHONCD = ZYKT.APKIHONCD AND SHMV.SHOPCD = ZYKT.SHOPCD AND ZYKT.SOKOCD = #{sokocd, jdbcType=VARCHAR} AND SHMV.SHNCD = ZYKT.SHNCD AND ZYKT.SHIMEDYDM = #{shimedydm, jdbcType=VARCHAR} ) LEFT OUTER JOIN S02M046T SHPM ON( SHMV.APKIHONCD = SHPM.APKIHONCD AND SHMV.SHOPCD = SHPM.SHOPCD ) LEFT OUTER JOIN S02M041T SKOM ON( SHMV.APKIHONCD = SKOM.APKIHONCD AND SHMV.SHOPCD = SKOM.SHOPCD AND SKOM.SOKOCD = #{sokocd, jdbcType=VARCHAR} ) LEFT OUTER JOIN S02M031T HKNM ON( SKOM.APKIHONCD = HKNM.APKIHONCD AND SKOM.SHOPCD = HKNM.SHOPCD AND SKOM.DLVRYKYOTENCD = HKNM.DLVRYKYOTENCD ) LEFT OUTER JOIN S02M036T SCGM ON( SCGM.LCTGRYCD = SHMV.LCTGRYCD AND SCGM.MCTGRYCD = '000' AND SCGM.SCTGRYCD = '000' ) LEFT OUTER JOIN S02M006T SYKM1 ON ( SYKM1.APKIHONCD = '000' AND SYKM1.SHOPCD = '000' AND SYKM1.RCRDKBN = 'M' AND SYKM1.SETTEINO = '037' AND SYKM1.SETTEICD = SHMV.SZ ) LEFT OUTER JOIN S02M006T SYKM2 ON ( SYKM2.APKIHONCD = '000' AND SYKM2.SHOPCD = '000' AND SYKM2.RCRDKBN = 'M' AND SYKM2.SETTEINO = '013' AND SYKM2.SETTEICD = SHMV.URITANI ), ( SELECT TTSM.TNSHAMEI FROM S02M003T TTSM WHERE TTSM.APKIHONCD = #{userApkihoncd, jdbcType=VARCHAR} AND TTSM.SHOPCD = #{userShopcd, jdbcType=VARCHAR} AND TTSM.TNSHACD = #{tnshacd, jdbcType=VARCHAR} ) TTSM1 WHERE SHMV.ZAIKOKANRITRGTFLG = '1' AND SHMV.SHOPYUKOKBN = '1' AND SHMV.APKIHONCD = #{apkihoncd, jdbcType=VARCHAR} AND SHMV.SHOPCD = #{shopcd, jdbcType=VARCHAR}
AND SHMV.LCTGRYCD = #{lctgrycd, jdbcType=VARCHAR}
ORDER BY SHMV.LCTGRYCD, SHMV.SHNCD
